/* Presentation and human-reviewed operations. No model or external agent calls. */
(function(root){
  'use strict';
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const time=x=>x?new Date(x).toLocaleString('zh-CN'):'未记录';
  const button=(text,op,id='',cls='')=>`<button type="button" class="${cls}" data-op="${op}" data-id="${esc(id)}">${esc(text)}</button>`;
  const modes={increment:'新增批次',snapshot:'当前总量观测',correction:'更正原批次'};
  const scenarioList=[['normal','初始规划','六个接送组、15 人；先比较同一输入的两种安排。'],['ruian-roads','瑞安真实道路','演练点位绑定公开道路；路线按道路方向与连通性计算。'],['road-closure','道路中断','核实演练路段受阻后，重新计算受影响路线。'],['village-growth','村级新增 12 人','含需协助 3 人、其中轮椅 1 人；此固定样例已核实，可另从现场端演示待核实流程。'],['resource-shortage','车辆资源不足','有限车辆无法覆盖全部人员，保留未安排清单。'],['shelter-loss','接收点停用','查看其他接收点余位与无法安排的原因。']];
  const guideSteps=[['选择情景 · 20 秒','先用“初始规划”了解约束，再切换“瑞安真实道路”查看路线。','ops-scenarios'],['现场上报 · 35 秒','打开现场网页，选择村庄和集合点；用语音或文字上报新增 12 人、需协助 3 人、含轮椅 1 人，可以分组。','village-ledger'],['核实需求 · 30 秒','在待办中打开上报，核对人数口径、协助需求和原话，采纳后才进入接送需求。','ops-pending'],['比较重算 · 35 秒','核实一条道路受阻，或登记资源停用；对照草案、原方案与基线，查看具体缺口。','planning-panel'],['人工执行 · 40 秒','核对草案后发布，登记联系并开始模拟执行；现场快捷登记接收、上车和到达，到达后由指挥台核验。','task-panel'],['复盘导出 · 20 秒','查看未解决事项、来源与计算版本，导出 JSON；导入时撤销旧发布状态，重新核对草案。','ops-report']];
  let adapter,dialog,guide=0,paused=false,imported=null,dialogRevision=null,dialogSession=null;
  function pending(state){const d=state.data,items=[],push=(key,title,detail,next,op,id,createdAt)=>items.push({key,title,detail,next,op,id,createdAt,...(d.followups?.[key]||{})});
    for(const r of d.villageReports||[])if(r.status==='pending'||r.status==='accepted'&&r.needsInfo)push('village:'+r.id,r.status==='pending'?'村级上报待核实':'村级接送信息待补',`${r.id} · ${modes[r.mode]} ${r.people} 人`,r.status==='pending'?'核对人数口径与原话':'补集合点、协助人数与同行关系',r.status==='pending'?'village-review':'village-complete',r.id,r.createdAt);
    for(const r of d.reports||[])if(['pending','accepted','coordination'].includes(r.status))push('report:'+r.id,r.status==='pending'?'现场反馈待核实':'现场事项待处理',r.text,r.status==='pending'?'核实现场事实':'登记处理结果；道路恢复须核实',r.status==='pending'?'review':'resolve',r.id,r.createdAt);
    for(const h of d.scenario.households)if(d.stage[h.id]==='arrived')push('verify:'+h.id,'人员到达待核验',`${h.name} · ${h.people} 人`,'核对现场到达情况后，完成人工核验','execution','',d.log?.[0]?.time);
    for(const id of state.blockedVehicles||[]){const v=d.scenario.vehicles.find(x=>x.id===id);push('blocked:'+id,'执行任务受阻',v?.name||id,'核实路况和资源，重算草案','generate','',d.log?.[0]?.time);}
    for(const h of d.plan?.unassigned||[])push('person:'+h.id,'仍有人员待协调',`${h.name} · ${h.people} 人 · ${h.reason||'约束不足'}`,'核实适配车辆、通行与接收点余位','ledger','',d.plan.createdAt);
    for(const h of d.scenario.households)if(d.stage[h.id]==='waiting'&&!d.contacts[h.id]?.contacted)push('contact:'+h.id,'责任联系未落实',`${h.name} · ${h.people} 人`,'实际完成联系后，在任务进展登记','execution','',d.createdAt);
    for(const [kind,list] of [['vehicle',d.scenario.vehicles],['shelter',d.scenario.shelters]])for(const x of list)if(!x.available)push(kind+':'+x.id,'资源暂不可用',x.name+' · '+(x.unavailableReason||'待核实'), '核实恢复条件或协调替代资源','resource','',x.availabilityUpdatedAt);
    return items;
  }
  function pendingHTML(state){const items=pending(state),urgent=items.filter(x=>/^(village:|report:|blocked:|verify:)/.test(x.key)),other=items.filter(x=>!urgent.includes(x));
    const cards=list=>list.map(x=>`<article class="ops-task"><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p>${x.owner||x.note?`<small>${esc(x.owner||'待指定负责人')}${x.note?' · '+esc(x.note):''}</small>`:''}<p class="boundary">下一步：${esc(x.next)}</p></div><div class="actions">${button(x.key.startsWith('verify:')?'去核验':'处理','go',x.op+'|'+x.id,'primary small')}${x.key.startsWith('verify:')?'':button('跟进备注','followup',x.key,'small quiet')}</div></article>`).join('');
    return `<section class="panel" id="ops-pending"><div class="panel-head"><div><h2>优先处理 <span class="badge ${urgent.length?'red':''}">${urgent.length}</span></h2><p>待核实的上报、受阻的任务、到达待核验。</p></div></div><div class="ops-pending-list">${urgent.length?cards(urgent):'<div class="empty"><strong>暂无需要核实的现场变化</strong><p>收到新上报会在这里提示；可以先查看转移安排。</p></div>'}</div>${other.length?`<details id="coordination-backlog" class="compact-disclosure"><summary>其他待跟进事项 · ${other.length} 项（联系、资源与人员缺口）</summary><div class="ops-pending-list">${cards(other)}</div></details>`:''}</section>`;
  }
  function dashboard(state){if(!state.capabilities?.operations)return '<div class="notice warn">当前服务仍是旧版。新版情景与恢复功能需启动 V3.5，或访问最新 GitHub 网页。</div>';return `<section class="ops-banner no-print"><div><span class="eyebrow">SCENARIO / REVIEW / REPLAY</span><h2>把变化转成下一步行动</h2><p>当前：${esc(state.data.scenarioTitle||state.data.scenario?.region?.name||'合成演练')} · 演练 ${esc(state.data.exerciseId||state.session.slice(0,8))}</p></div><div class="actions">${button('3 分钟演示引导','guide','','primary')}${button('切换演练情景','scenarios')}${button('备份与恢复','backup')}${button('数据与依据','evidence')}${button('评估结果','evaluation')}</div></section>`;}
  function sources(){const lib=root.JiaoyingEvidence||{};return `<div class="ops-evidence"><h3>数据来源目录</h3><p>公开道路与合成业务分开记录；下列公开性不等于赛事已认可该地图来源。</p>${(lib.sources||[]).map(x=>`<article class="ops-source"><strong>${esc(x.title||x.name)}</strong><p>${esc(x.kind||x.type||x.nature||'')} · ${esc(x.publisher||x.institution||'')}</p><p>${esc(x.usage||x.use||x.purpose||'')}</p><p class="boundary">${esc(x.license||'许可见原出处')} ${esc(x.access||x.method||'')}</p>${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noreferrer">查看原始来源 ↗</a>`:''}</article>`).join('')}<h3>公开预案参考卡</h3><p>条款支撑流程设计，不批准某条路线，也不是本系统的官方授权。</p>${(lib.policies||[]).map(x=>`<article class="ops-source"><strong>${esc(x.title)}</strong><p>${esc(x.publisher)} · ${esc(x.date)} · ${esc(x.jurisdiction)}</p><p>${esc(x.section)} · ${esc(x.summary)}</p><p>项目推导：${esc(x.application)}</p><p class="boundary">${esc(x.boundary)} · ${esc(x.status)}</p><p class="boundary">${esc(x.version||'')}</p><a href="${esc(x.url)}" target="_blank" rel="noreferrer">打开条款出处 ↗</a></article>`).join('')||'<p>未检索到可引用的公开条款。</p>'}<p class="boundary">${esc((lib.limits||[]).map(x=>typeof x==='string'?x:[x.label,x.status,x.detail].filter(Boolean).join('：')).join('；'))}</p></div>`;}
  function details(state,reportMode=false){const d=state.data,p=d.plan,b=d.baseline;return `<section class="panel" ${reportMode?'':'id="ops-comparison"'}><div class="panel-head"><div><h2>分配明细与失效应对</h2><p>按当前剩余任务比较；已上车保持原车，未确认的草案不会替换已发布任务。</p></div>${reportMode?'':button('登记资源变化','resource','','small')}</div><div class="panel-body">${p&&b?`<div class="table-wrap"><table><thead><tr><th>车辆</th><th>优化草案</th><th>规则基线</th></tr></thead><tbody>${d.scenario.vehicles.map(v=>`<tr><th>${esc(v.name)}</th><td>${routeText(p,v.id,d)}</td><td>${routeText(b,v.id,d)}</td></tr>`).join('')}</tbody></table></div><h3>接收点余位与本次安排</h3><div class="table-wrap"><table><thead><tr><th>演练接收点</th><th>当前已占 / 容量</th><th>草案新安排</th><th>基线新安排</th></tr></thead><tbody>${d.scenario.shelters.map(x=>`<tr><th>${esc(x.name)}${x.available?'':' · 停用'}</th><td>${d.occupancy[x.id]||0} / ${x.capacity}</td><td>${p.routes.filter(r=>r.shelterId===x.id).reduce((a,r)=>a+r.people,0)}</td><td>${b.routes.filter(r=>r.shelterId===x.id).reduce((a,r)=>a+r.people,0)}</td></tr>`).join('')}</tbody></table></div><details><summary>逐组接到时间与协助需求（演练分钟）</summary><div class="table-wrap"><table><thead><tr><th>接送组</th><th>协助人数</th><th>草案接到</th><th>基线接到</th></tr></thead><tbody>${d.scenario.households.filter(h=>d.stage[h.id]==='waiting').map(h=>`<tr><th>${esc(h.name)}</th><td>${h.assistancePeople??(h.assistance?h.people:0)}</td><td>${arrival(p,h.id)}</td><td>${arrival(b,h.id)}</td></tr>`).join('')}</tbody></table></div></details>`:'<p>执行输入已更新，请重新计算剩余任务，才能比较同一快照。</p>'}<details><summary>资源变化如何处理</summary><p>先登记已核实的车辆或接收点失效；系统保留车上人员并计算新草案。没有可行送达方案时原车待协调，不自动换车，不增加虚构运力。恢复资源也需说明核实依据。</p></details>${diagnosticHTML(state)}${state.diagnostics?`<details><summary>约束与变更诊断（可审计计算结果）</summary><pre class="ops-json">${esc(JSON.stringify(state.diagnostics,null,2))}</pre></details>`:''}</div></section>`;}
  function diagnosticHTML(state){const x=state.diagnostics;if(!x)return '';const changes=x.changes||[],same=state.data.scenario.vehicles.filter(v=>!changes.some(c=>c.vehicleId===v.id)),wait=x.comparison?.assistedWait;return `<div class="notice"><strong>${x.constraints.checked?(x.constraints.ok?'演练硬约束校验通过':'约束存在问题，请核对'):'暂无新草案可校验'}</strong><p>${esc(x.constraints.scope)}</p>${wait?`<p>已安排协助人员等待：草案 ${wait.optimized??'—'} / 基线 ${wait.baseline??'—'} 人·分钟。请同时比较协助人数覆盖，未安排人员不计入此值。</p>`:''}</div>${state.data.plan&&state.data.activePlan?`<h3>本次改变与保留</h3>${changes.map(c=>`<p><strong>${esc(c.vehicleName)}</strong>：${esc((c.before?.stops||[]).join(' → ')||'无剩余接人')} / ${esc(c.before?.shelterId||'原车待协调')} → ${esc((c.after?.stops||[]).join(' → ')||'无剩余接人')} / ${esc(c.after?.shelterId||'原车待协调')}；${c.before?.people||0} → ${c.after?.people||0} 人。</p>`).join('')}<p>保持不变：${same.map(v=>esc(v.name)).join('、')||'无'}。草案仍需人工核对后发布。</p>`:''}${x.unassigned?.length?`<h3>每项缺口如何跟进</h3>${x.unassigned.map(h=>`<div class="notice warn"><strong>${esc(h.name)} · ${h.people} 人</strong><p>${esc(h.reason)}</p><p>建议下一步：${esc(h.next)}</p></div>`).join('')}`:''}`;}
  function routeText(p,id,d){const r=p.routes.find(x=>x.vehicleId===id);if(!r||(!r.people&&!r.holding))return '未分配';const names=r.stops.map(x=>d.scenario.households.find(h=>h.id===x.id)?.name||x.id);return `${r.people} 人 · ${esc(names.join(' → ')||'已有车上人员')}<br><small>${r.holding?'原车待协调':esc(d.scenario.shelters.find(s=>s.id===r.shelterId)?.name||'')+' · '+r.finish+' 分抵达'}</small>`;}
  function arrival(p,id){const r=p.routes.find(x=>x.stops.some(s=>s.id===id)),st=r?.stops.find(x=>x.id===id);return st?esc(st.arrival??st.arrive??st.time??'见路线记录'):'未安排';}
  function report(state){const d=state.data,items=pending(state);return `<section id="ops-report" class="ops-report"><h3>复盘附录 · V${esc(root.JiaoyingCapabilities?.version||'3.5')}</h3><p>演练编号 ${esc(d.exerciseId||state.session)} · 保存时间 ${time(state.savedAt)} · 记录版本 ${d.revision}</p><p>草案 ${esc(d.plan?.id||'无')}；发布方案 ${esc(d.activePlan?.id||'无')}；确认时间 ${time(d.activePlan?.publishedAt)}；确认说明 ${esc(d.activePlan?.note||'尚未确认')}</p><h4>未解决事项（${items.length}）</h4>${items.map(x=>`<p>${esc(x.title)}：${esc(x.detail)}；负责人 ${esc(x.owner||'待指定')}；下一步 ${esc(x.next)}${x.note?'；跟进 '+esc(x.note):''}</p>`).join('')||'<p>无上述待办。</p>'}<h4>村级批次与更正</h4>${(d.villageReports||[]).map(r=>`<p>${esc(r.id)} / ${esc(modes[r.mode])} / ${r.people} 人 / ${esc(r.status)}${r.targetId?' / 更正 '+esc(r.targetId):''}；原话 ${esc(r.text)}；核实说明 ${esc(r.note||'未填写')}</p>`).join('')||'<p>暂无村级批次。</p>'}<h4>现场反馈与处置</h4>${(d.reports||[]).map(r=>`<p>${esc(r.id)} · ${esc(r.text)} · ${esc(r.status)} · ${esc(r.note||'')} · ${esc(r.resolution||'')}</p>`).join('')||'<p>暂无现场反馈。</p>'}${details(state,true)}<h4>数据与工具边界</h4><p>规则整理 + 路径与资源计算；DeepSeek / Agent / 彩云实况未接入。天气为演练一小时累计毫米，位置为节点登记。真实路网也使用演练速度和道路状态，不能作为安全导航。</p>${sources()}</section>`;}
  function show(title,body){dialogRevision=adapter.state().data.revision;dialogSession=adapter.state().session;dialog.innerHTML=`<div class="dialog-body"><div class="close-row"><h2>${title}</h2>${button('关闭','close')}</div>${body}<p id="ops-error" role="alert"></p></div>`;if(!dialog.open)dialog.showModal();}
  function backup(){const st=adapter.state();show('备份与恢复',`<p>演练 ${esc(st.data.exerciseId||st.session)} · 记录 ${st.data.revision}</p><p>${st.capabilities.persistentStorage?'已提交记录自动保存；最近 '+time(st.savedAt):'当前服务未开启磁盘保存'}。备份文件仍需自行保留。</p><div class="actions">${button('导出完整 JSON','export','','primary')}<label class="button">选择 JSON 恢复文件<input id="ops-import" type="file" accept=".json,application/json" hidden></label></div><div id="ops-import-preview"></div><p class="boundary">恢复会替换两个网页的当前演练。旧发布方案会撤销，已上车与到达台账保留，重新生成待核对草案；坏文件不会覆盖当前记录。不会自动补提交未确认的表单。</p>`);}
  function guideModal(){const step=guideSteps[guide];show('3 分钟核心演示',`<p class="ops-guide-number">${guide+1} / ${guideSteps.length} ${paused?'· 引导已暂停':''}</p><h3>${step[0]}</h3><p>${step[1]}</p><p>此引导只导航，不自动填报、核实或发布。可随时继续当前演练。</p><div class="actions">${guide===1?'<a class="button primary" href="./#field" target="_blank" rel="noopener">打开现场网页上报 ↗</a>':button('定位操作区域','guide-locate',step[2],'primary')}${button(guide?'上一步':'从此开始','guide-prev')}${button(guide===5?'回到第一步':'下一步','guide-next')}${button(paused?'继续引导':'暂停引导','guide-pause')}</div><p class="boundary">完整参赛讲解建议 8—10 分钟；此处是其中约 3 分钟的实际操作。</p>`);}
  function init(a){adapter=a;dialog=document.createElement('dialog');dialog.id='operations-dialog';document.body.append(dialog);
    document.addEventListener('click',async e=>{const el=e.target.closest('[data-op]');if(!el)return;e.preventDefault();const op=el.dataset.op,id=el.dataset.id,st=adapter.state();if(!st)return;try{
      if(op==='close'){dialog.close();return;}if(op==='guide'){guideModal();return;}if(op==='guide-prev'){guide=Math.max(0,guide-1);guideModal();return;}if(op==='guide-next'){guide=(guide+1)%6;guideModal();return;}if(op==='guide-pause'){paused=!paused;guideModal();return;}
      if(op==='guide-locate'){dialog.close();if(id==='ops-scenarios'){adapter.locate?.('ops-scenarios');adapter.notify('点击“切换演练情景”选择起始状态。');return;}if(id==='ops-report'){adapter.go('report','');return;}if(adapter.locate)adapter.locate(id);else document.getElementById(id)?.scrollIntoView({block:'start',behavior:'smooth'});return;}
      if(op==='scenarios'){show('选择演练情景',`<p>可继续现有演练，也可载入固定样例。载入将替换当前记录，请先导出需要保留的结果。</p><div class="ops-scenarios">${scenarioList.map(([id,name,detail])=>`<article><h3>${name}</h3><p>${detail}</p>${button('查看并载入','scenario-preview',id)}</article>`).join('')}</div>`);return;}
      if(op==='scenario-preview'){const x=scenarioList.find(x=>x[0]===id);show('载入：'+esc(x[1]),`<p>${x[2]}</p><p>当前两端记录将替换。算法会现场计算结果；样例不是历史灾情。</p><div class="actions">${button('先导出当前记录','export')}${button('确认替换并载入','scenario-load',id,'danger')}</div>`);return;}
      if(op==='scenario-load'){el.disabled=true;await adapter.action('scenario',{id},dialogRevision,dialogSession);dialog.close();adapter.notify('情景已载入；计算结果是待人工核对的草案。');return;}
      if(op==='backup'){backup();return;}if(op==='export'){adapter.export();return;}
      if(op==='restore'){if(!imported)throw Error('请先选择有效文件');el.disabled=true;await adapter.action('restore',{data:imported},dialogRevision,dialogSession);dialog.close();imported=null;adapter.notify('存档已恢复，发布状态已撤销，请重新核对草案。');return;}
      if(op==='evidence'){show('数据与公开预案',sources());return;}if(op==='evaluation'){show('固定情景评估','<p>正在读取本版本实际计算结果…</p>');const r=await fetch('assets/evaluation.json');if(!r.ok)throw Error('评估文件暂不可用');const data=await r.json();show('固定情景评估',`<p>相同输入、相同资源与约束。表内来自实际求解；没有接入模型，不能用于宣称 AI 效果。</p><div class="table-wrap"><table><thead><tr><th>情景</th><th>基线覆盖</th><th>优化覆盖</th><th>未安排</th><th>约束错误</th><th>优化耗时中位数</th></tr></thead><tbody>${data.cases.map(x=>`<tr><th>${esc(x.name)}</th><td>${x.baseline.servedPeople} / ${x.people}</td><td>${x.optimized.servedPeople} / ${x.people}</td><td>${x.optimized.unassignedPeople}</td><td>${x.optimized.validationErrors.length}</td><td>${x.optimized.timing.medianMs} ms</td></tr>`).join('')}</tbody></table></div><p>这是开发环境计算耗时，不是用户设备承诺。覆盖对象不同，不能将等待下降直接解释为同一批人提速。失败场景仍保留未安排人员。</p><a href="assets/evaluation.json" target="_blank" rel="noopener">打开完整输入哈希、指标与规模测量 JSON ↗</a>`);return;}
      if(op==='go'){const [name,...rest]=id.split('|');adapter.go(name,rest.join('|'));return;}
      if(op==='followup'){const item=pending(st).find(x=>x.key===id);if(!item)throw Error('事项已更新');show('责任与跟进',`<p>${esc(item.title)} · ${esc(item.detail)}</p><label for="ops-owner">演练负责人 / 角色</label><input id="ops-owner" maxlength="40" value="${esc(item.owner||'指挥值守')}" required><label for="ops-due">约定跟进时间（演练设定，非官方时限）</label><input id="ops-due" type="datetime-local"><label for="ops-note">本次跟进回执</label><textarea id="ops-note" maxlength="300">${esc(item.note||'')}</textarea>${button('保存跟进记录','followup-save',id,'primary')}<p class="boundary">保存不改变业务事实。需要到对应业务中完成核实或处理，事项才会从待办消失。</p>`);return;}
      if(op==='followup-save'){const owner=document.getElementById('ops-owner').value.trim(),note=document.getElementById('ops-note').value.trim(),due=document.getElementById('ops-due').value;if(!owner||!note)throw Error('请填写负责人和跟进说明');el.disabled=true;await adapter.action('followup',{key:id,owner,note,dueAt:due?new Date(due).toISOString():null,status:'working'},dialogRevision,dialogSession);dialog.close();return;}
      if(op==='resource'){show('登记已核实的资源变化',`<p>适用于准备阶段与执行途中；既有车上人员保持原车。只登记已核实的演练变化。</p><label for="ops-resource">车辆 / 接收点</label><select id="ops-resource">${[['vehicle',st.data.scenario.vehicles],['shelter',st.data.scenario.shelters]].map(([kind,list])=>list.map(x=>`<option value="${kind}|${esc(x.id)}">${esc(x.name)} · 当前${x.available?'可用':'停用'}</option>`).join('')).join('')}</select><label for="ops-available">核实结果</label><select id="ops-available"><option value="false">停用 / 故障</option><option value="true">恢复可用</option></select><label for="ops-reason">现场核实依据</label><textarea id="ops-reason" maxlength="300" placeholder="如：演练现场确认车辆故障，人员仍在原车等待协调"></textarea>${button('保存变化并计算草案','resource-save','','danger')}`);return;}
      if(op==='resource-save'){const [kind,id]=document.getElementById('ops-resource').value.split('|'),reason=document.getElementById('ops-reason').value.trim();if(reason.length<5)throw Error('请填写至少 5 字的核实依据');el.disabled=true;await adapter.action('resource-event',{kind,id,available:document.getElementById('ops-available').value==='true',reason},dialogRevision,dialogSession);dialog.close();return;}
    }catch(error){el.disabled=false;const out=document.getElementById('ops-error');if(dialog.open&&out)out.textContent=error.message;else adapter.notify(error.message);}});
    document.addEventListener('change',async e=>{if(e.target.id!=='ops-import')return;imported=null;const out=document.getElementById('ops-import-preview');try{const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024)throw Error('文件超过 5 MB');const value=JSON.parse(await file.text()),data=value.data||value;if(data.schema!=='jiaoying-v3'||!data.scenario||!Array.isArray(data.scenario.households))throw Error('不是兼容的演练存档');imported=data;out.innerHTML=`<div class="notice"><h3>待恢复：${esc(file.name)}</h3><p>${data.scenario.households.length} 个记录组 · 输入 v${esc(data.inputVersion)} · 旧记录 ${esc(data.revision)}</p><p>点击后会完整校验人数、引用关系和执行台账；校验失败保持现状。</p>${button('确认校验并替换当前演练','restore','','danger')}</div>`;}catch(error){out.textContent='不能读取：'+error.message;}});
  }
  root.JiaoyingOperations={init,dashboard,pendingHTML,details,report,sources,pending};
})(window);
